# IVS Local Backend + Metro Startup Script (PowerShell)\n# Usage: .\start-ivs-dev.ps1\n# Requires: .env.ivs-local configured with AWS credentials + Stage ARN\n\n$ErrorActionPreference = \"Stop\"\n\nWrite-Host \"\" -ForegroundColor Green\nWrite-Host \"=== Blyp IVS Local Dev Startup ===\" -ForegroundColor Green\nWrite-Host \"\"\n\n# Check if .env.ivs-local exists\nif (-not (Test-Path \".env.ivs-local\")) {\n    Write-Host \"ERROR: .env.ivs-local not found\" -ForegroundColor Red\n    Write-Host \"Please configure .env.ivs-local first (see docs/IVS_LOCAL_SETUP.md)\" -ForegroundColor Yellow\n    exit 1\n}\n\n# Load env from .env.ivs-local\nWrite-Host \"Loading .env.ivs-local...\" -ForegroundColor Cyan\n$envContent = Get-Content \".env.ivs-local\" | Where-Object { $_ -notmatch \"^#\" -and $_ -notmatch \"^$\" }\nforeach ($line in $envContent) {\n    $parts = $line -split \"=\", 2\n    if ($parts.Length -eq 2) {\n        [System.Environment]::SetEnvironmentVariable($parts[0].Trim(), $parts[1].Trim(), \"Process\")\n    }\n}\n\n# Verify required env vars\n$required = @(\"AWS_REGION\", \"AWS_ACCESS_KEY_ID\", \"AWS_SECRET_ACCESS_KEY\", \"IVS_STAGE_ARN\")\nforeach ($var in $required) {\n    $value = [System.Environment]::GetEnvironmentVariable($var, \"Process\")\n    if (-not $value -or $value -eq \"REPLACE_WITH_YOUR_ACCESS_KEY_ID\") {\n        Write-Host \"ERROR: $var not properly configured\" -ForegroundColor Red\n        exit 1\n    }\n}\n\nWrite-Host \"✓ Env vars loaded\" -ForegroundColor Green\n\n# Start IVS backend in new window\nWrite-Host \"\"\nWrite-Host \"Starting IVS backend server (port 3001)...\" -ForegroundColor Cyan\n$backendCmd = \"node local-ivs-server.js\"\nStart-Process -NoNewWindow -FilePath \"powershell\" -ArgumentList \"-NoExit\", \"-Command\", $backendCmd -PassThru\n\nStart-Sleep -Seconds 2\n\n# Start Metro in new window\nWrite-Host \"Starting Metro bundler...\" -ForegroundColor Cyan\nWrite-Host \"  EXPO_PUBLIC_API_BASE_URL=$env:EXPOSE_PUBLIC_API_BASE_URL\" -ForegroundColor Gray\nWrite-Host \"  EXPO_PUBLIC_STREAMING_BACKEND=$env:EXPO_PUBLIC_STREAMING_BACKEND\" -ForegroundColor Gray\nWrite-Host \"\"\n\n$env:EXPO_PUBLIC_API_BASE_URL = \"http://192.168.1.236:3001\"\n$env:EXPO_PUBLIC_STREAMING_BACKEND = \"IVS\"\n$env:EXPO_PUBLIC_IVS_DEV_BYPASS = \"\"  # Ensure bypass is OFF\n\n$metroCmd = \"npx expo start --dev-client --clear\"\nStart-Process -NoNewWindow -FilePath \"powershell\" -ArgumentList \"-NoExit\", \"-Command\", $metroCmd -PassThru\n\nWrite-Host \"\"\nWrite-Host \"=== All services started ===\" -ForegroundColor Green\nWrite-Host \"Backend: http://localhost:3001\" -ForegroundColor Cyan\nWrite-Host \"Metro: Check Metro terminal window\" -ForegroundColor Cyan\nWrite-Host \"\"\nWrite-Host \"Next: Open Blyp app on device and tap Go Live\" -ForegroundColor Yellow\n"